USE pare_castells;

-- Asegura los campos necesarios sin crear familias automáticamente
ALTER TABLE fallers MODIFY email VARCHAR(255) NULL;
ALTER TABLE fallers MODIFY data_alta DATE NULL;
ALTER TABLE fallers ADD COLUMN IF NOT EXISTS familia_id INT NULL;

CREATE TEMPORARY TABLE IF NOT EXISTS tmp_fallers (
  nom VARCHAR(100),
  cognoms VARCHAR(100),
  domicili VARCHAR(255),
  telefon VARCHAR(50),
  dni VARCHAR(50),
  data_naixement DATE,
  email VARCHAR(255),
  edat INT,
  familia_name VARCHAR(255),
  grup VARCHAR(100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

TRUNCATE TABLE tmp_fallers;


-- Inserta los falleros sin asignar familia
SELECT t.nom, t.cognoms, t.domicili, t.telefon, t.dni, t.data_naixement, t.email, t.edat, NULL, t.grup
FROM tmp_fallers t;

DROP TEMPORARY TABLE IF EXISTS tmp_fallers;
